var ICON_RE = /^(mdi:[a-z0-9-]{1,50}|custom:[a-z0-9_-]{1,24})$/;

function iconOk(n) {
  return typeof n === "string" && (!!IC[n] || ICON_RE.test(n));
}

function pathOk(d) {
  return (
    typeof d === "string" && d.length >= 8 && d.length <= 4000 && /^[0-9A-Za-z\s.,+-]+$/.test(d)
  );
}

function svg(n) {
  if (IC[n]) return "<svg viewBox='0 0 24 24'>" + IC[n] + "</svg>";
  var p = STORE.icons && STORE.icons[n];
  if (p && pathOk(p))
    return "<svg viewBox='0 0 24 24'><path fill='currentColor' stroke='none' d='" + p + "'/></svg>";
  return "<svg viewBox='0 0 24 24'>" + IC.info + "</svg>";
}

function ic(n) {
  return "<span class='ic'>" + svg(n) + "</span>";
}

var ICONSHARD = {};

function iconShard(key) {
  var c = /^[a-z]/.test(key) ? key[0] : "0";
  return (
    ICONSHARD[c] ||
    (ICONSHARD[c] = fetch(appFile("mdi/" + c + ".json")).then(function (r) {
      if (!r.ok) throw new Error("missing");
      return r.json();
    }))
  );
}

function iconFetchPath(name) {
  if (ICONPATH[name]) return Promise.resolve(ICONPATH[name]);
  var key = name.slice(4);
  return iconShard(key).then(function (shard) {
    var d = shard[key];
    if (!pathOk(d)) throw new Error("missing");
    ICONPATH[name] = d;
    return d;
  });
}

var ICONQ = [],
  ICONBUSY = 0,
  ICONLOADING = null;

function iconPump() {
  while (ICONBUSY < 6 && ICONQ.length) {
    (function (j) {
      ICONBUSY++;
      iconFetchPath(j[0])
        .then(j[1], j[2])
        .then(function () {
          ICONBUSY--;
          iconPump();
        });
    })(ICONQ.shift());
  }
}

function iconPathQ(name) {
  return new Promise(function (res, rej) {
    ICONQ.push([name, res, rej]);
    iconPump();
  });
}

function iconListLoad(cb) {
  if (ICONLIST) return cb(ICONLIST);
  if (ICONLOADING) {
    ICONLOADING.push(cb);
    return;
  }
  ICONLOADING = [cb];
  fetch(appFile("mdi/index.json"))
    .then(function (r) {
      return r.json();
    })
    .then(function (l) {
      ICONLIST = (Array.isArray(l) ? l : [])
        .filter(function (x) {
          return Array.isArray(x) && typeof x[0] === "string" && /^[a-z0-9-]{1,50}$/.test(x[0]);
        })
        .map(function (x) {
          return { name: x[0], kw: String(x[1] || "") };
        });
    })
    .catch(function () {
      ICONLIST = [];
    })
    .then(function () {
      var q = ICONLOADING;
      ICONLOADING = null;
      q.forEach(function (f) {
        f(ICONLIST);
      });
    });
}

/* The built-in icons are named in one word; these are the words they stand for. */
var ICONNAMES = {
  ac: "Air conditioner",
  bedking: "Bed king",
  bedsingle: "Bed single",
  cam: "Camera",
  camoff: "Camera off",
  cctv: "CCTV",
  chdown: "Channel down",
  chev: "Chevron",
  chup: "Channel up",
  eyeoff: "Eye off",
  mic: "Microphone",
  phone: "Phone",
  playc: "Play circle",
  playpause: "Play pause",
  powerset: "Power set",
  prev: "Previous",
  rec: "Record",
  sd: "SD card",
  thermo: "Thermometer",
  tv: "TV",
  vac: "Vacuum",
  voldown: "Volume down",
  volup: "Volume up",
};

function iconLabel(n) {
  var s = String(n)
    .replace(/^(mdi|custom):/, "")
    .replace(/[-_]+/g, " ");
  s = ICONNAMES[s] || s;
  return s.charAt(0).toUpperCase() + s.slice(1);
}

function iconSvg(p) {
  return "<svg viewBox='0 0 24 24'><path fill='currentColor' stroke='none' d='" + p + "'/></svg>";
}

var ICONLIST = null,
  ICONPATH = {};

function iconPick(list, cur, fn) {
  var wrap = mk("div", "idd"),
    isOpen = false,
    items = [],
    view = [],
    shown = 0,
    io = null,
    q = "";
  var btn = mk("div", "pill pane");
  function paintBtn() {
    btn.innerHTML =
      ic(cur && iconOk(cur) ? cur : "info") +
      "<span class='tx'><span class='nm'></span><span class='sb'></span></span><span class='chev'>" +
      svg("chev") +
      "</span>";
    btn.querySelector(".nm").textContent = cur ? iconLabel(cur) : _T("choose_an_icon");
    btn.querySelector(".sb").textContent = _T("tap_to_see_all_icons");
  }
  paintBtn();
  var panel = mk("div", "idd-panel pane");
  panel.style.display = "none";
  var sw = mk("div", "sqw pane", svg("search")),
    inp = mk("input", "sq");
  inp.type = "text";
  inp.placeholder = _T("search_icons");
  inp.setAttribute("autocomplete", "off");
  inp.setAttribute("autocapitalize", "off");
  sw.appendChild(inp);
  panel.appendChild(sw);
  var listEl = mk("div", "idd-list");
  panel.appendChild(listEl);
  var foot = mk("div", "idd-foot"),
    addBtn = mk("div", "idd-add");
  addBtn.textContent = _T("add_your_own_icon");
  foot.appendChild(addBtn);
  panel.appendChild(foot);
  var form = mk("div");
  form.style.display = "none";
  foot.appendChild(form);
  var ni = mk("input", "sq"),
    pi = mk("input", "sq");
  ni.type = "text";
  ni.maxLength = 24;
  ni.placeholder = _T("icon_name_like_garage");
  pi.type = "text";
  pi.placeholder = _T("path_data_of_a_24_by_24_svg_icon");
  [ni, pi].forEach(function (x) {
    var w2 = mk("div", "sqw pane");
    w2.appendChild(x);
    form.appendChild(w2);
  });
  var go2 = mk("div", "rbtn pane");
  go2.textContent = _T("add_and_use_this_icon");
  form.appendChild(go2);
  addBtn.addEventListener("click", function () {
    form.style.display = form.style.display === "none" ? "" : "none";
  });
  go2.addEventListener("click", function () {
    var nm = ni.value
        .trim()
        .toLowerCase()
        .replace(/[^a-z0-9_-]+/g, "-")
        .replace(/^-+|-+$/g, "")
        .slice(0, 24),
      d = pi.value.trim();
    if (!nm) {
      toast(_T("give_the_icon_a_name"));
      return;
    }
    if (!pathOk(d)) {
      toast(_T("that_path_data_isn_t_valid"));
      return;
    }
    STORE.icons = STORE.icons || {};
    if (Object.keys(STORE.icons).length >= 300) {
      toast(_T("too_many_extra_icons_remove_some_fir"));
      return;
    }
    STORE.icons["custom:" + nm] = d;
    done("custom:" + nm);
  });
  function done(n) {
    cur = n;
    fn(n);
    if (!IC[n]) storeChanged();
    paintBtn();
    close();
  }
  function choose(n) {
    if (IC[n] || (STORE.icons && STORE.icons[n])) return done(n);
    iconFetchPath(n)
      .then(function (p) {
        STORE.icons = STORE.icons || {};
        if (Object.keys(STORE.icons).length >= 300) {
          toast(_T("too_many_extra_icons_remove_some_fir"));
          return;
        }
        STORE.icons[n] = p;
        done(n);
      })
      .catch(function () {
        toast(_T("couldn_t_load_that_icon"));
      });
  }
  function build() {
    var seen = {};
    items = [];
    function add(n, kw) {
      if (seen[n]) return;
      seen[n] = 1;
      items.push({ n: n, kw: kw || "" });
    }
    list.forEach(function (n) {
      add(n);
    });
    Object.keys(IC).forEach(function (n) {
      add(n);
    });
    Object.keys(STORE.icons || {}).forEach(function (n) {
      add(n);
    });
    (ICONLIST || []).forEach(function (x) {
      add("mdi:" + x.name, x.kw);
    });
    filter();
  }
  function filter() {
    var toks = q.toLowerCase().split(/\s+/).filter(Boolean);
    view = toks.length
      ? items.filter(function (it) {
          var h = it.n.toLowerCase() + " " + it.kw;
          return toks.every(function (k) {
            return h.indexOf(k) >= 0;
          });
        })
      : items;
    shown = 0;
    listEl.innerHTML = "";
    listEl.scrollTop = 0;
    if (!view.length) {
      var e = mk("div", "hint");
      e.textContent = _T("no_icons_found");
      listEl.appendChild(e);
    }
    more();
  }
  function more() {
    var end = Math.min(view.length, shown + 60);
    for (var i = shown; i < end; i++) listEl.appendChild(row(view[i].n));
    shown = end;
  }
  function row(n) {
    var r = mk("div", "idd-row" + (n === cur ? " sel" : "")),
      p = (STORE.icons && STORE.icons[n]) || ICONPATH[n],
      g = mk("span", "ic", IC[n] ? svg(n) : p ? iconSvg(p) : svg("info")),
      l = mk("span", "idd-n");
    l.textContent = iconLabel(n);
    r.appendChild(g);
    r.appendChild(l);
    r.dataset.n = n;
    r.addEventListener("click", function () {
      choose(n);
    });
    if (!IC[n] && !p && io) io.observe(r);
    return r;
  }
  listEl.addEventListener("scroll", function () {
    if (listEl.scrollTop + listEl.clientHeight > listEl.scrollHeight - 160 && shown < view.length)
      more();
  });
  if (window.IntersectionObserver)
    io = new IntersectionObserver(
      function (es) {
        es.forEach(function (e) {
          if (!e.isIntersecting) return;
          io.unobserve(e.target);
          var n = e.target.dataset.n;
          iconPathQ(n)
            .then(function (p) {
              var g = e.target.querySelector(".ic");
              if (g) g.innerHTML = iconSvg(p);
            })
            .catch(function () {
              e.target.style.opacity = ".4";
            });
        });
      },
      { root: listEl }
    );
  inp.addEventListener("input", function () {
    q = inp.value;
    filter();
  });
  function openIt() {
    isOpen = true;
    panel.style.display = "";
    build();
    iconListLoad(function () {
      if (isOpen) {
        build();
      }
    });
    setTimeout(function () {
      try {
        inp.focus();
        panel.scrollIntoView({ block: "nearest", behavior: "smooth" });
      } catch (e) {}
    }, 60);
  }
  function close() {
    isOpen = false;
    panel.style.display = "none";
    if (io) io.disconnect();
  }
  btn.addEventListener("click", function () {
    if (isOpen) close();
    else openIt();
  });
  wrap.appendChild(btn);
  wrap.appendChild(panel);
  return wrap;
}

function cleanIcons(m) {
  var o = {};
  if (m && typeof m === "object")
    Object.keys(m)
      .slice(0, 300)
      .forEach(function (k) {
        if (ICON_RE.test(k) && pathOk(m[k])) o[k] = m[k];
      });
  return o;
}

/* Shared building blocks: pills, sliders, menus, dialogs, round buttons, tiles and rows, entity pickers, picture helpers. */

/* The page was scrolled at this moment (any scroll container). A touch that only stops a scroll, or that happens while the page scrolls, is not a tap. */
var SCROLLAT = 0;
document.addEventListener(
  "scroll",
  function () {
    SCROLLAT = Date.now();
  },
  true
);

/* A slider row. The row only reacts to a slide that is clearly horizontal: a finger that moves up or down is scrolling the page, and a touch that stops a scroll is not a tap. */
function attachSlide(el, h) {
  var sx = 0,
    sy = 0,
    t0 = 0,
    down = false,
    moved = false,
    scrolling = false,
    rect = null,
    tgt = null,
    held = false,
    timer = 0;
  function frac(e) {
    return Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
  }
  el.addEventListener("pointerdown", function (e) {
    down = true;
    moved = false;
    t0 = Date.now();
    /* The touch that stops a scrolling page is not meant for the row. */
    scrolling = t0 - SCROLLAT < 300;
    sx = e.clientX;
    sy = e.clientY;
    tgt = e.target;
    rect = el.getBoundingClientRect();
    dragging++;
    DRAGAT = Date.now();
    watchRelease(e.pointerId);
    capturePointer(el, e);
    held = false;
    clearTimeout(timer);
    if (h.onHold)
      timer = setTimeout(function () {
        if (down && !moved && !scrolling && SCROLLAT < t0 && !editing()) {
          held = true;
          h.onHold();
        }
      }, 450);
  });
  el.addEventListener("pointermove", function (e) {
    if (!down || held || scrolling) return;
    if (!moved) {
      var dx = Math.abs(e.clientX - sx),
        dy = Math.abs(e.clientY - sy);
      if (dy > 8 && dy >= dx) {
        scrolling = true;
        clearTimeout(timer);
        return;
      }
      if (dx > 10 && dx > 1.8 * dy) {
        moved = true;
        clearTimeout(timer);
      }
    }
    if (moved) h.onMove(frac(e));
  });
  /* The release is also heard on the window: when the finger lets go away from the row (or the row was replaced meanwhile) the row itself gets no pointerup, and a missing release would stop every refresh of the page. */
  function watchRelease(pid) {
    function fin(ev) {
      if (ev.pointerId !== pid) return;
      window.removeEventListener("pointerup", fin, true);
      window.removeEventListener("pointercancel", fin, true);
      if (ev.type === "pointerup") up(ev);
      else cancel();
    }
    window.addEventListener("pointerup", fin, true);
    window.addEventListener("pointercancel", fin, true);
  }
  function up(e) {
    if (!down) return;
    down = false;
    clearTimeout(timer);
    dragging = Math.max(0, dragging - 1);
    if (held) {
      held = false;
      if (h.onCancel) h.onCancel();
      return;
    }
    if (moved) h.onCommit(frac(e));
    else if (scrolling || SCROLLAT >= t0) {
      if (h.onCancel) h.onCancel();
    } else if (h.onTap) h.onTap(tgt);
  }
  function cancel() {
    if (down) {
      down = false;
      held = false;
      clearTimeout(timer);
      dragging = Math.max(0, dragging - 1);
      if (h.onCancel) h.onCancel();
    }
  }
  el.addEventListener("pointerup", up);
  el.addEventListener("pointercancel", cancel);
}

/* A popup's main action (Save, Done) stays pinned to the bottom of the popup instead of sitting after a long list. */
/* The press effect, for everything that can be pressed: one rule for all of it. The element shrinks (class pressed) while the finger is on it, for at least 110 ms so a quick tap shows it too, and it lets go as soon as the finger starts to drag or scroll. */
var PRESSABLE =
  ".pill:not(.static),.tile,.sel,.rnd,.rbtn,.opt,.rb-chip,.room,.qa,.swc,.tact,.camt,.dock .di,.menu .mi,.gb[role=button],.lp-it,.lp-bri-btn,.lp-style,.lp-mode,.lp-tile";
document.addEventListener(
  "pointerdown",
  function (e) {
    if (e.button || !e.target.closest) return;
    var el = e.target.closest(PRESSABLE);
    if (!el) return;
    var t0 = Date.now(),
      x = e.clientX,
      y = e.clientY;
    el.classList.add("pressed");
    function end() {
      document.removeEventListener("pointerup", end, true);
      document.removeEventListener("pointercancel", end, true);
      document.removeEventListener("pointermove", move, true);
      setTimeout(function () {
        el.classList.remove("pressed");
      }, Math.max(0, 110 - (Date.now() - t0)));
    }
    function move(ev) {
      if (Math.abs(ev.clientX - x) > 10 || Math.abs(ev.clientY - y) > 10) end();
    }
    document.addEventListener("pointerup", end, true);
    document.addEventListener("pointercancel", end, true);
    document.addEventListener("pointermove", move, true);
  },
  true
