function lzone(id) {
  var m = LMEM[id];
  if (!m) {
    m = deviceGet("db_lzone_" + id, {});
    LMEM[id] = m;
  }
  var a = A(id),
    ch = false;
  if (a.hs_color && JSON.stringify(a.hs_color) !== JSON.stringify(m.hs)) {
    m.hs = a.hs_color;
    ch = true;
  }
