    return "hs_color" in x ? "c" : "color_temp_kelvin" in x ? "w" : "b";
  }
  s.q = s.q.filter(function (x) {
    return ty(x) !== ty(data);
  });
  s.q.push(data);
  if (s.busy) return;
  s.busy = true;
  (function next() {
    var d = s.q.shift();
    if (!d) {
      s.busy = false;
      return;
    }
    setTimeout(
      function () {
        s.at = Date.now();
        call("light", "turn_on", d);
        next();
