function cleanHdr(a) {
  var out = [];
  (Array.isArray(a) ? a : []).slice(0, 4).forEach(function (x) {
    if (!x || ["weather", "people", "lights", "entity"].indexOf(x.k) < 0) return;
    var o = { k: x.k };
