  (r && Array.isArray(r.btns) ? r.btns : []).slice(0, 60).forEach(function (x) {
    if (!x || typeof x.e !== "string" || !ENTRE.test(x.e)) return;
    if (["script", "button", "input_button", "scene", "switch"].indexOf(x.e.split(".")[0]) < 0) return;
