      : null;
  }
  if (!ruleOk(src) && !ed) return null;
  var pc = CURSCOPE,
    pe = CURSEC;
  CURSCOPE = scopeKey(q[0]);
  CURSEC = src;
  try {
    return secBuildEl(src);
  } finally {
    CURSCOPE = pc;
    CURSEC = pe;
  }
}

function secLinkPage(b, key) {
