    a.textContent = fmtNum(gmax) + (u0 ? " " + u0 : "");
    var b = mk("div", "ax lo");
    b.textContent = fmtNum(gmin) + (u0 ? " " + u0 : "");
    wrap.appendChild(a);
    wrap.appendChild(b);
  }
  box.appendChild(wrap);
