/* ---- wall mode: idle clock or photo screensaver ---- */
var WALL = { t: 0, el: null, tick: 0, photo: 0, booted: false };

function isNight() {
  var s = S("sun.sun");
  if (s) return s.state === "below_horizon";
  var hr = new Date().getHours();
  return hr >= 22 || hr < 6;
}

function wallApply() {
  document.body.classList.toggle("wallnight", !!(PREFS.wall && PREFS.wallDim && isNight()));
  if (!PREFS.wall) wallHide();
  else wallReset();
}

function wallReset() {
  clearTimeout(WALL.t);
  if (WALL.el || !PREFS.wall) return;
  WALL.t = setTimeout(wallShow, PREFS.wallIdle * 1000);
}

function wallShow() {
  if (WALL.el) return;
  var el = mk("div", "wall"),
    c = mk(
      "div",
      "wall-c",
      "<div class='wall-t'></div><div class='wall-d'></div><div class='wall-w'></div>"
    );
  var photos = (PREFS.wallMode === "photo" && STORE.cfg && STORE.cfg.wallPhotos) || [],
    img = null;
  if (photos.length) {
    img = document.createElement("img");
    img.alt = "";
    el.appendChild(img);
    var showPhoto = function () {
      var i2 = Math.floor(Date.now() / 30000) % photos.length;
      if (img.dataset.i === String(i2)) return;
      img.dataset.i = String(i2);
      img.classList.remove("in");
      setTimeout(
        function () {
          if (!WALL.el) return;
          img.onload = function () {
            img.classList.add("in");
          };
          img.src = photos[i2];
        },
        img.getAttribute("src") ? 900 : 0
      );
    };
    showPhoto();
    WALL.photo = setInterval(showPhoto, 3000);
  }
  el.appendChild(c);
  document.body.appendChild(el);
  WALL.el = el;
  el.addEventListener(
    "click",
    function (e) {
      e.stopPropagation();
      e.preventDefault();
      wallHide();
    },
    true
  );
  WALL.tick = setInterval(wallTick, 1000);
  wallTick();
}

function wallTick() {
  var el = WALL.el;
  if (!el) return;
  var d = new Date(),
    w = null;
  Object.keys(H().states).some(function (k) {
    if (k.indexOf("weather.") === 0) {
      w = H().states[k];
      return true;
    }
    return false;
  });
  el.querySelector(".wall-t").textContent = tfmt(d, { hour: "numeric", minute: "2-digit" });
  el.querySelector(".wall-d").textContent = d.toLocaleDateString(LOC(), {
    weekday: "long",
    day: "numeric",
    month: "long",
  });
  el.querySelector(".wall-w").textContent =
    w && w.attributes && w.attributes.temperature !== undefined
      ? Math.round(w.attributes.temperature) + "° · " + cap(String(w.state).replace(/-/g, " "))
      : "";
  el.classList.toggle("dim", !!(PREFS.wallDim && isNight()));
  var m = d.getMinutes();
  el.querySelector(".wall-c").style.transform =
    "translate(" + ((m % 7) - 3) * 5 + "px," + ((m % 5) - 2) * 5 + "px)";
}

function wallHide() {
  if (!WALL.el) return;
  clearInterval(WALL.tick);
  clearInterval(WALL.photo);
  WALL.el.remove();
  WALL.el = null;
  wallReset();
}

function wallBoot() {
  if (WALL.booted) return;
  WALL.booted = true;
  ["pointerdown", "keydown", "touchstart"].forEach(function (ev) {
    document.addEventListener(
      ev,
      function () {
        if (!WALL.el) wallReset();
      },
      { passive: true, capture: true }
    );
  });
  setInterval(function () {
    document.body.classList.toggle("wallnight", !!(PREFS.wall && PREFS.wallDim && isNight()));
  }, 60000);
  wallApply();
  var ob = mk("div", "offbar");
  ob.setAttribute("role", "status");
  ob.textContent = _T("home_assistant_disconnected_reconnec");
  document.body.appendChild(ob);
  document.addEventListener("keydown", function (e) {
    if (WALL.el) {
      e.preventDefault();
      wallHide();
      return;
    }
    if (e.key === "Tab" && !KBD) {
      KBD = true;
      a11yScan();
    }
    if (e.key === "Escape") {
      if (SHEET) closeSheet();
      return;
    }
    if (!PREFS.a11y && !KBD) return;
    var el = e.target;
    if (
      (e.key === "Enter" || e.key === " ") &&
      el &&
      el.getAttribute &&
      el.getAttribute("role") === "button"
    ) {
      e.preventDefault();
      el.click();
    }
    if (e.key === "Tab") sheetTrap(e);
  });
}

/* Backups: automatic snapshots, export, import and restore. */

/* ---- automatic backups: snapshots of the dashboard setup kept in HA system data ---- */
var BK_KEY = "dashboard_backups";

function bkOn() {
  return !!(STORE.cfg && STORE.cfg.autobackup);
}

function bkCfg() {
  var c = STORE.cfg || {};
  return { keep: c.backupKeep || 5, every: c.backupEvery || 6 };
}

function bkList() {
  return storeGet(BK_KEY).then(function (l) {
    return Array.isArray(l) ? l : [];
  });
}

function bkWrite(list) {
  return HA.data.set("system", BK_KEY, list);
}

function bkAdd(json, force) {
  if (!ISADMIN || !bkOn() || !json) return Promise.resolve(false);
  return bkList()
    .then(function (list) {
      var cfg = bkCfg(),
        last = list.length ? list[list.length - 1].t : 0;
      if (!force && Date.now() - last < cfg.every * 3600000) return false;
      list.push({ t: Date.now(), by: (H().user && H().user.name) || "", j: json });
      while (list.length > cfg.keep) list.shift();
      return bkWrite(list).then(function () {
        return true;
      });
    })
    .catch(function () {
      return false;
    });
}

