function downloadBackup() {
  var blob = new Blob([exportJSON()], { type: "application/json" }),
    a = document.createElement("a"),
    d = new Date(),
    p = function (n) {
      return ("0" + n).slice(-2);
    };
  a.href = URL.createObjectURL(blob);
  a.download =
    "dashboard-backup-" +
    d.getFullYear() +
    p(d.getMonth() + 1) +
    p(d.getDate()) +
    "-" +
    p(d.getHours()) +
    p(d.getMinutes()) +
    ".json";
  document.body.appendChild(a);
  a.click();
  setTimeout(function () {
    a.remove();
    URL.revokeObjectURL(a.href);
  }, 1000);
}

