        : [sc.room],
    offL = [],
    byDom = {};
  sc.acts.forEach(function (a) {
    if (a.live) return;
    listed[a.id] = 1;
    var m = A(a.id).entity_id;
    if (Array.isArray(m))
      m.forEach(function (x) {
