/* ---- loading the plugins' scripts ---- */

var PLUGINS_LOADED = {};

/* Loads the script of each plus integration that has one, once, for administrators only: what a plugin adds is for the people who change things. */
function pluginsLoad() {
  if (!ISADMIN) return;
  HA.plugins().then(
    function (list) {
      (Array.isArray(list) ? list : []).forEach(function (p) {
        if (PLUGINS_LOADED[p.id] || !/^\/[a-z0-9_]+_static\/[A-Za-z0-9_.\/-]+\.js$/.test(p.menu) || p.menu.indexOf("..") >= 0) return;
        PLUGINS_LOADED[p.id] = true;
        var s = document.createElement("script");
        s.src = p.menu + (p.version ? "?v=" + encodeURIComponent(p.version) : "");
        s.async = false;
        /* What the plugin registered (scenes, devices, styles) was not there when the page was first drawn: draw it again once it is. */
        s.onload = function () {
          if (BOOTED) rerender();
        };
        document.head.appendChild(s);
      });
    },
    function () {}
  );
}

/* Saved colours and white temperatures. They belong to a room, not to a light: a colour saved from one light is there on the other lights of the room and on its lights master. Each is one colour ({h, s}) or one white temperature ({k}); colours kept together are a scene. */

var SAVED_MAX = 40;

/* What was saved for single lights before they belonged to rooms moves to the room of its light, once. */
function savedMigrate() {
  var old = STORE.presets || {};
  if (!Object.keys(old).length) return;
  STORE.saved = STORE.saved || {};
  Object.keys(old).forEach(function (id) {
    var room = ownerRoom(id) || "home",
      list = (STORE.saved[room] = STORE.saved[room] || []);
    (old[id] || []).forEach(function (p) {
      if (p.z || list.length >= SAVED_MAX) return;
      if (
        !list.some(function (x) {
          return same(x, p);
        })
      )
        list.push(p);
    });
  });
  STORE.presets = {};
  if (ISADMIN) storeChanged();
}

function savedOf(room) {
  savedMigrate();
  return (STORE.saved && STORE.saved[room]) || [];
}

/* The room whose saved colours a popup shows: the room of its first light. */
function savedRoomOf(ids) {
  for (var i = 0; i < ids.length; i++) {
    var r = ownerRoom(ids[i]);
    if (r) return r;
  }
  return VIEW !== "home" && UIROOM[VIEW] ? VIEW : "home";
}

function savedAdd(room, p) {
  var list = savedOf(room);
  if (
    list.some(function (x) {
      return same(x, p);
    })
  ) {
    toast(_T("already_saved"));
    return false;
  }
  if (list.length >= SAVED_MAX) {
    toast(_T("saved_limit_reached"));
    return false;
  }
  STORE.saved = STORE.saved || {};
  STORE.saved[room] = list.concat([p]);
  storeChanged();
  return true;
}

function savedRemove(room, p) {
  STORE.saved[room] = savedOf(room).filter(function (x) {
    return pkeyP(x) !== pkeyP(p);
  });
  storeChanged();
}

/* The one colour or white temperature that saving takes from what is selected: the first of its lights that is on (a group whose lights are set alike is that colour). Null, with a word to the person, when none is on. */
function savedCapture(n) {
  var on = lightIndividuals(n.cmd).filter(isOn)[0];
  if (!on) {
    toast(_T("turn_the_light_on_to_save_its_colour"));
    return null;
  }
  var c = curPreset(on);
  /* A light made of zones is saved as the colour of its first zone. */
  if (c && c.z) c = { h: c.z[0].h, s: c.z[0].s };
  if (!c) {
    toast(_T("turn_the_light_on_to_save_its_colour"));
    return null;
  }
  return c;
}

/* The saved colours and temperatures of every room, to copy one into this room. */
function savedAllPage(b, room) {
  var rooms = Object.keys(STORE.saved || {}).filter(function (r) {
      return r !== room && savedOf(r).length;
    }),
    box = mk("div");
  b.appendChild(box);
  if (!rooms.length) {
    box.appendChild(pill("info", _T("nothing_saved_in_other_rooms"), {}));
    return;
  }
  box.appendChild(mkHint(_T("tap_a_saved_colour_to_add_it_to_this_room")));
  rooms.forEach(function (r) {
    box.appendChild(sep(TITLES[r] || r, "home"));
    var row = mk("div", "pre");
    savedOf(r).forEach(function (p) {
      row.appendChild(
        swatch(p, {
          act: savedOf(room).some(function (x) {
            return same(x, p);
          }),
          tap: function () {
            if (savedAdd(room, p)) toast(_T("added_to_this_room"));
            refresh();
          },
        })
      );
    });
    box.appendChild(row);
  });
}

/* The light popup as part of an editor: the same popup a light has on the dashboard, opened over a scene editor. The lights follow every change at once (a preview); the checkmark keeps what they show in the scene, and leaving after a change asks whether to keep it or put the lights back as they were. */

var LIT = null;

/* What each of the lights was doing, so a preview can be undone. */
function lightSnapshot(ids) {
  return lightIndividuals(ids).map(function (id) {
    var a = A(id);
    return {
      id: id,
      on: V_(id) === "on",
      brightness: a.brightness,
      hs: a.hs_color,
      k: a.color_mode === "color_temp" ? a.color_temp_kelvin : null,
    };
  });
}

function lightRestore(snap) {
  snap.forEach(function (s) {
    if (!s.on) {
      callRaw("light", "turn_off", { entity_id: s.id });
      return;
    }
    var d = { entity_id: s.id };
    if (s.brightness) d.brightness = s.brightness;
    if (s.k) d.color_temp_kelvin = s.k;
    else if (s.hs) d.hs_color = s.hs;
    callRaw("light", "turn_on", d);
  });
}

/* What the scene should make one light do: off, or on with the brightness and colour it shows now. */
function lightAct(id) {
  if (V_(id) !== "on") return { id: id, on: false };
  var a = A(id),
    act = { id: id, on: true };
  if (typeof a.brightness === "number") act.bri = Math.max(1, Math.min(100, Math.round(a.brightness / 2.55)));
  /* A light playing an effect is kept as that effect, not as the colour it passes through. */
  if (a.effect && a.effect !== "off") act.fx = a.effect;
  else if (a.color_mode === "color_temp" && a.color_temp_kelvin) act.col = { k: Math.round(a.color_temp_kelvin) };
  else {
    var hs = lpHs(id);
    if (hs) act.col = { h: Math.round(hs[0]), s: Math.round(hs[1]) };
  }
  return act;
}

/* The acts for what the popup shows: a group that was separated gives one act for each light, lights joined by hand give each of their lights the same. */
function lightActsOf(S, id) {
  var units = S ? lpVisible(S) : [{ key: id, cmd: [id] }],
    out = [],
    seen = {};
  units.forEach(function (u) {
    (u.virtual ? u.cmd : [u.key]).forEach(function (e) {
      if (!seen[e]) {
        seen[e] = 1;
        out.push(lightAct(e));
      }
    });
  });
  return out;
}

/* Opens the light popup for editing. o: { id, name, icon, onTick(acts) }. */
function openLightEditor(o) {
  LIT = { id: o.id, name: o.name, icon: o.icon, onTick: o.onTick, S: null };
  showPopup("light-edit", true, o.after || true);
}

function lightEditDef() {
  var lt = LIT;
  return {
    title: lt.name,
    icon: lt.icon || "light",
    build: function (b) {
      var snap = lightSnapshot([lt.id]);
      lightPopup(b, lt.id, {
        ready: function (S) {
          lt.S = S;
        },
      });
      /* The light shows what it is changed to while this is open. Closing after a change asks; the checkmark puts the light's settings into the scene. */
      guardUnsaved({
        dirty: function () {
          return JSON.stringify(lightSnapshot([lt.id])) !== JSON.stringify(snap);
        },
        save: function (leave) {
          lt.onTick(lightActsOf(lt.S, lt.id));
          POPGUARD = null;
          leave();
          return true;
        },
        discard: function () {
          lightRestore(snap);
        },
      });
    },
  };
}

/* The same for several lights at once (a room's, a scene's): the light popup of the group, opened over whatever asks for it. Every light may be switched on from it, the lights follow each change at once, and the checkmark keeps what they show: o.onSave(acts) gets one act for each light and answers true (or a promise of true) when it kept them, false when it did not (the popup stays open). Leaving after a change asks; discarding puts the lights back as they were. o: { name, icon, lights, onSave(acts), after }. */
var LIE = null;

function openLightsEditor(o) {
  LIE = { name: o.name, icon: o.icon, lights: o.lights.slice(), onSave: o.onSave };
  var lights = LIE.lights;
  /* The popup groups the lights that look the same when it opens. Lights changed just before (a scene played to edit it) report one by one, so it waits until they have stopped changing, or the grouping would be of how they were and not of how they are. */
  var last = JSON.stringify(lightSnapshot(lights)),
    steady = Date.now(),
    began = steady;
  (function check() {
    var now = Date.now(),
      cur = JSON.stringify(lightSnapshot(lights));
    if (cur !== last) {
      last = cur;
      steady = now;
    }
    if (now - steady >= 600 || now - began >= 4000) {
      showPopup("lights-edit", true, o.after || true);
      return;
    }
    setTimeout(check, 150);
  })();
}

function lightsEditDef() {
  var le = LIE;
  return {
    title: le.name,
    icon: le.icon || "lights",
    build: function (b) {
      var snap = lightSnapshot(le.lights);
      LMASTER["edit"] = le.lights;
      LMASTER_NAME["edit"] = le.name;
      LMASTER_ALL["edit"] = true;
      LWHEEL["m:edit"] = undefined;
      lightsMasterPopup(b, "edit");
      guardUnsaved({
        dirty: function () {
          return JSON.stringify(lightSnapshot(le.lights)) !== JSON.stringify(snap);
        },
        save: function (leave) {
          return Promise.resolve(le.onSave(lightUnits(le.lights).map(lightAct))).then(function (ok) {
            if (ok === false) return false;
            POPGUARD = null;
            leave();
            return true;
          });
        },
        discard: function () {
          lightRestore(snap);
        },
      });
    },
  };
}

/* Making a scene: the + button of a scenes section, the question what kind (a classic scene of fixed settings, or a live scene), the areas a live scene plays in, and the guard that asks before an editor throws changes away. */

/* An editor with something to save asks before it is left, by any way: back, the scrim, the close button, and has a checkmark next to the close button that saves it (popupCheck). The same for every
   place that saves: the scene editors, the area editor, the light editor, a device in the Hue Plus menu.
   o.dirty() says whether there is anything to lose; o.save(leave) saves and goes on to `leave`, and gives back false when it did not save (no name yet) or a promise of true or false when the save takes a while
   (the bridge); o.discard() undoes what was previewed. o.done is what the checkmark goes on to after saving (the page before, unless the editor closes the popup). o.inner marks a page that is only one step of a larger edit (the choices of a device): going back from it to the rest of the edit does not ask, closing does. */
function guardUnsaved(o) {
  function guard(leave) {
    if (!o.dirty()) return false;
    if (o.inner && leave === popBack) return false;
    askSheet(_T("unsaved_changes"), [
      {
        label: _T("save"),
        fn: function () {
          guard.save(leave);
        },
      },
      {
        label: _T("discard_changes"),
        fn: function () {
          POPGUARD = null;
          if (o.discard) o.discard();
          leave();
        },
      },
    ]);
    return true;
  }
  /* The Save of the question and the checkmark. A save that did not happen keeps the editor open, and the guard with it. */
  guard.save = function (leave) {
    POPGUARD = null;
    var done = o.save(leave);
    if (done === false) POPGUARD = guard;
    else if (done && done.then)
      done.then(function (ok) {
        if (ok === false) POPGUARD = guard;
      });
  };
  guard.done = o.done || popBack;
  POPGUARD = guard;
  if (!o.inner) popupCheck(guard);
}

/* The + on a scenes section, for administrators: it makes a scene and puts it in this section. */
function sceneAddButton(scope, e) {
  var b = mk("div", "rnd pane sm secact", svg("plus"));
