  });
  return out;
}

/* What the light popup returned replaces the acts of that light and of the lights it is made of. */
function staticSetLightActs(rootId, acts) {
  var drop = {},
    kept = [],
    at = -1;
  staticLightFamily(rootId).forEach(function (id) {
