/* Lights that exist only in the dashboard. The live scene maker uses them for the colours of a scene: one light named Colors, made of up to 10 colour lights the way a gradient light is made of zones, so the light popup controls them like any other light. They answer for their own state and take commands (colour, white temperature, brightness) without Home Assistant knowing of them. */

var VCOL_MAX = 10;
var VCOL_GROUP = "light.lm_colors";

function vcolId(i) {
  return "light.lm_c" + (i + 1);
}

function vlightIs(id) {
  return typeof id === "string" && !!VLIGHT[id];
}

function vcolState(id, attrs) {
  return {
    entity_id: id,
    state: "on",
    attributes: Object.assign(
      { supported_color_modes: ["hs", "color_temp"], min_color_temp_kelvin: 2000, max_color_temp_kelvin: 6500 },
      attrs
    ),
    last_changed: new Date().toISOString(),
  };
}

/* The colour lights of a palette ({hs}, {k} or {xy}, and b when dimmer than full). A colour given as xy keeps its exact value until it is changed. */
function vcolLoad(palette) {
  VLIGHT = {};
  var ids = [];
  palette.slice(0, 16).forEach(function (c, i) {
    var id = vcolId(i),
      a = { friendly_name: _T("colour") + " " + (i + 1), brightness: Math.round((c.b || 100) * 2.55) };
    if (c.k) {
      a.color_mode = "color_temp";
      a.color_temp_kelvin = c.k;
    } else {
      var hs = c.hs || liveXyHs(c.xy[0], c.xy[1]);
      a.color_mode = "hs";
      a.hs_color = [hs[0], hs[1]];
    }
    VLIGHT[id] = vcolState(id, a);
    if (c.xy) VLIGHT[id].xy = { value: c.xy, hs: a.hs_color.slice() };
    ids.push(id);
  });
  VLIGHT[VCOL_GROUP] = vcolState(VCOL_GROUP, {
    friendly_name: _T("colours"),
    entity_id: ids,
    zone_colors: ids,
    zone_label: _T("colour"),
  });
  vcolSync();
}

function vcolIds() {
  return (VLIGHT[VCOL_GROUP] && VLIGHT[VCOL_GROUP].attributes.entity_id) || [];
}

/* The group shows what its colours show: the first one's colour and the mean brightness. */
function vcolSync() {
  var g = VLIGHT[VCOL_GROUP];
  if (!g) return;
  var kids = vcolIds().map(function (id) {
      return VLIGHT[id];
    }),
    first = kids[0];
  g.attributes.zone_colors = kids.map(function (k) {
    return k.attributes.hs_color || k.attributes.color_temp_kelvin;
  });
  g.attributes.brightness = Math.round(
    kids.reduce(function (s, k) {
      return s + k.attributes.brightness;
    }, 0) / Math.max(1, kids.length)
  );
  ["color_mode", "hs_color", "color_temp_kelvin"].forEach(function (key) {
    if (first && first.attributes[key] !== undefined) g.attributes[key] = first.attributes[key];
    else delete g.attributes[key];
  });
}

/* A colour added at the end, as the colour next to it, or white if there is none yet. */
function vcolAdd() {
  var ids = vcolIds();
  if (ids.length >= VCOL_MAX) return null;
  var id = vcolId(ids.length),
    last = ids.length ? VLIGHT[ids[ids.length - 1]] : null,
    a = last ? Object.assign({}, last.attributes) : { color_mode: "color_temp", color_temp_kelvin: 4000, brightness: 255 };
  a.friendly_name = _T("colour") + " " + (ids.length + 1);
  VLIGHT[id] = vcolState(id, a);
  VLIGHT[VCOL_GROUP].attributes.entity_id = ids.concat(id);
  vcolSync();
  return id;
}

function vcolRemove(id) {
  var ids = vcolIds();
  if (ids.length <= 1 || ids.indexOf(id) < 0) return false;
  var left = ids.filter(function (x) {
    return x !== id;
  });
  /* The colours keep their numbers in order. */
  var kept = left.map(function (x) {
    return VLIGHT[x];
  });
  VLIGHT = { };
  var out = [];
  kept.forEach(function (st, i) {
    var nid = vcolId(i);
    st.entity_id = nid;
    st.attributes.friendly_name = _T("colour") + " " + (i + 1);
    VLIGHT[nid] = st;
    out.push(nid);
  });
  VLIGHT[VCOL_GROUP] = vcolState(VCOL_GROUP, { friendly_name: _T("colours"), entity_id: out, zone_colors: out, zone_label: _T("colour") });
  vcolSync();
  return true;
}

/* The palette the colour lights show now, in the form a live scene keeps. */
function vcolPalette() {
  return vcolIds().map(function (id) {
    var st = VLIGHT[id],
      a = st.attributes,
      pct = Math.max(10, Math.min(100, Math.round(a.brightness / 2.55))),
      o;
    if (a.color_mode === "color_temp") o = { k: Math.round(a.color_temp_kelvin) };
    else if (st.xy && st.xy.hs[0] === a.hs_color[0] && st.xy.hs[1] === a.hs_color[1]) o = { xy: st.xy.value };
    else o = { hs: [Math.round(a.hs_color[0]), Math.round(a.hs_color[1])] };
    if (pct < 99.5) o.b = pct;
    return o;
  });
}

function vlightApply(id, s, data) {
  var st = VLIGHT[id],
    a = st.attributes;
  if (Array.isArray(a.entity_id)) {
    a.entity_id.forEach(function (k) {
      vlightApply(k, s, data);
    });
    vcolSync();
    return;
  }
  /* A colour of a scene is always there; it can be changed, not switched off. */
  if (s !== "turn_on") return;
  if (typeof data.brightness_pct === "number") a.brightness = Math.max(1, Math.min(255, Math.round(data.brightness_pct * 2.55)));
  if (typeof data.brightness === "number") a.brightness = Math.max(1, Math.min(255, Math.round(data.brightness)));
  if (Array.isArray(data.hs_color)) {
    a.color_mode = "hs";
    a.hs_color = [data.hs_color[0], data.hs_color[1]];
    delete a.color_temp_kelvin;
  } else if (typeof data.color_temp_kelvin === "number") {
    a.color_mode = "color_temp";
    a.color_temp_kelvin = data.color_temp_kelvin;
    delete a.hs_color;
  } else if (Array.isArray(data.xy_color)) {
    var hs = liveXyHs(data.xy_color[0], data.xy_color[1]);
    a.color_mode = "hs";
    a.hs_color = [hs[0], hs[1]];
    delete a.color_temp_kelvin;
  }
  st.last_changed = new Date().toISOString();
}

/* A command that names dashboard lights: they take theirs, and what is left for Home Assistant is returned (null when nothing is). */
function vlightDispatch(s, data) {
  var ids = data && data.entity_id,
    list = Array.isArray(ids) ? ids : ids ? [ids] : [];
  if (!list.some(vlightIs)) return data;
  list.filter(vlightIs).forEach(function (id) {
    vlightApply(id, s, data);
  });
  var real = list.filter(function (id) {
    return !vlightIs(id);
  });
  if (!real.length) return null;
  return Object.assign({}, data, { entity_id: Array.isArray(ids) ? real : real[0] });
}

/* The live scene maker. A live scene is a palette that moves across the lights of one or more areas. The maker is the light popup of the dashboard with one more light in it, Colors, whose colours are the palette: separate it into up to 10 colours, give each its colour and brightness, join a colour with a light to give that light the colour, turn the lights of the areas on and off, set each light's brightness and effect on its own tabs. Under the lights come the settings of the whole scene. The lights follow every change at once, as a preview; saving keeps what they show in the scene and puts the lights back as they were. */

var LMK = null;

/* An area of the editor: the one an import is about to create is only here until the scene is saved. */
function liveAreaOf(id) {
  return LMK && LMK.pending && LMK.pending.id === id ? LMK.pending : eaById(id);
}

function liveSceneAreas(sc) {
  return (sc.live.areas && sc.live.areas.length ? sc.live.areas : [sc.live.area]).map(liveAreaOf).filter(Boolean);
}

/* The area a scene plays in: one stored area, or for a scene made in the maker the lights of its areas without the ones it leaves off, under an id of the scene's own (this is also what Hue Plus is given). */
function liveSceneArea(sc) {
  var areas = liveSceneAreas(sc);
  if (!areas.length) return null;
  if (!sc.live.areas) return areas[0];
  var off = {},
    seen = {},
    lights = [];
  (sc.live.off || []).forEach(function (id) {
    off[id] = 1;
  });
  areas.forEach(function (a) {
    a.lights.forEach(function (l) {
      if (seen[l.id] || off[l.id]) return;
      seen[l.id] = 1;
      lights.push(l);
    });
  });
  return { id: sc.live.area, name: areas.map(function (a) { return a.name; }).join(" + "), room: areas[0].room, lights: lights.slice(0, 32), dummies: [] };
}

/* The live scenes that play in an area (their lights come from it). */
function liveScenesIn(areaId) {
  return STORE.scenes.filter(function (sc) {
    return sc.live && sc.live.areas && sc.live.areas.indexOf(areaId) >= 0;
  });
}

function liveMakerEdit(sc) {
  liveMakerOpen(sc.room, sc, null, sc.live.areas && sc.live.areas.length ? sc.live.areas : [sc.live.area].filter(Boolean));
}

/* New areas for the scene being edited: the lights follow, and the lights that leave go back as they were. */
function liveMakerSetAreas(list) {
  var before = LMK.lights;
  LMK.areas = list.slice();
  LMK.lights = liveMakerLights(LMK.areas);
  var gone = before.filter(function (id) {
    return LMK.lights.indexOf(id) < 0;
  });
  lightRestore(
    LMK.snap.filter(function (s) {
      return gone.indexOf(s.id) >= 0;
    })
  );
  LMK.snap = LMK.snap.filter(function (s) {
    return gone.indexOf(s.id) < 0;
  }).concat(
    lightSnapshot(
      LMK.lights.filter(function (id) {
        return before.indexOf(id) < 0;
      })
    )
  );
}

/* Every light of the areas, once. */
function liveMakerLights(areas) {
  var seen = {},
    out = [];
  areas.forEach(function (id) {
    var a = liveAreaOf(id);
    if (a)
      a.lights.forEach(function (l) {
        if (!seen[l.id] && H().states[l.id]) {
          seen[l.id] = 1;
          out.push(l.id);
        }
      });
  });
  return out;
}

/* draft (optional) is a scene made elsewhere (an import) to start from; pending an area that goes with it. */
function liveMakerOpen(room, sc, target, areas, draft, pending) {
  var src = sc || draft || null,
    live = src ? src.live : null;
  LMK = {
    room: room,
    isNew: !sc,
    target: target || null,
    pending: pending || null,
    id: sc ? sc.id : "",
    name: src ? src.name : "",
    icon: liveIcon(src),
    areas: areas.slice(),
    live: JSON.parse(
      JSON.stringify(
        live || { speed: 6, range: 100, bri: 100, fps: 2, spread: "x", src: "palette", mode: "linear", fx: [], looks: {}, also: [] }
      )
    ),
    /* What single lights do differently: their own brightness (percent) and their own effect, by light; the rest follows the scene. */
    bri: {},
    fx: {},
    looks0: (live && live.looks) || {},
    S: null,
    saved: null,
    preview: false,
    snap: [],
  };
  LMK.live.mode = LMK.live.mode === "segmented" ? "segmented" : "linear";
  Object.keys(LMK.looks0).forEach(function (id) {
    var look = LMK.looks0[id];
    if (typeof look.bri === "number") LMK.bri[id] = look.bri;
    if (look.native) LMK.fx[id] = look.native;
  });
  vcolLoad(live ? live.palette : [{ hs: [0, 100] }, { hs: [240, 100] }]);
  LMK.lights = liveMakerLights(LMK.areas);
  LMK.snap = lightSnapshot(LMK.lights);
  if (sc) liveMakerShowScene(sc);
  showPopup("live-edit", true);
}

/* An edited scene opens with its lights as it has them: the ones it uses on and the ones it leaves off. Their brightness and effects are the scene's, kept here (LMK.bri, LMK.fx), not set on the lights. */
function liveMakerShowScene(sc) {
  var off = {};
  (sc.live.off || []).forEach(function (id) {
    off[id] = 1;
  });
  LMK.lights.forEach(function (id) {
    callRaw("light", off[id] ? "turn_off" : "turn_on", { entity_id: id });
  });
}

/* What the editor holds, for telling whether there is anything to lose. */
function liveMakerSig() {
  return JSON.stringify({
    name: String(LMK.name || "").trim(),
    icon: LMK.icon,
    areas: LMK.areas,
    palette: vcolPalette(),
    live: LMK.live,
    lights: LMK.lights.map(function (id) {
      return [id, V_(id)];
    }),
    bri: LMK.bri,
    fx: LMK.fx,
  });
}

function liveMakerDirty() {
  return !!LMK && LMK.saved !== null && liveMakerSig() !== LMK.saved;
}

/* The scene as it is saved. */
function liveMakerScene() {
  var live = LMK.live,
    pal = vcolPalette(),
    off = [],
    looks = {};
  LMK.lights.forEach(function (id) {
    if (V_(id) !== "on") {
      off.push(id);
      return;
    }
    var k = {},
      before = LMK.looks0[id];
    if (typeof LMK.bri[id] === "number") k.bri = Math.max(1, Math.min(100, Math.round(LMK.bri[id])));
    if (LMK.fx[id] && LIVE_NATIVE.test(LMK.fx[id]) && LMK.fx[id] !== "off") k.native = LMK.fx[id];
    if (before && before.fx) k.fx = before.fx; /* brightness effects of a light, made elsewhere, are kept as they are */
    if (Object.keys(k).length) looks[id] = k;
  });
  var id = LMK.id || "s" + Date.now().toString(36);
  return {
    id: id,
    name: String(LMK.name || "").trim(),
    room: LMK.room,
    icon: LMK.icon,
    others: "keep",
    acts: [],
    live: {
      area: ("lx-" + id).slice(0, 24),
      areas: LMK.areas,
      off: off,
      palette: pal,
      speed: live.speed,
      range: live.range,
      bri: live.bri,
      fps: liveFps(live),
      spread: live.spread,
      src: live.src,
      mode: live.mode === "segmented" ? "segmented" : "linear",
      fx: live.fx,
      looks: looks,
      also: live.also || [],
    },
  };
}

function liveMakerStopPreview() {
