/* ---- change log with undo (admin) ---- */
var LOGKEY = "dashboard_log",
  LOGNEXT = false,
  LOGSKIP = false,
  LOGDATA = null,
  LOGPARTS = ["ui", "scenes", "presets", "access", "notify"];

var UIKEYLAB = {
    rooms: "rooms",
    devs: "devices",
    chips: "climate tiles",
    stat: "status tiles",
    bats: "batteries",
    layout: "layout",
    caps: "light features",
    on: "light defaults",
    newSince: "new devices",
    ignored: "ignored devices",
    meta: "names",
  },
  PARTLAB = {
    scenes: "scenes",
    saved: "saved colours",
    access: "access rules",
    sched: "schedules",
    notify: "notifications",
  };

function logDiff(prev, cur) {
  var parts = [],
    words = [];
  LOGPARTS.forEach(function (p) {
    if (JSON.stringify(prev[p]) === JSON.stringify(cur[p])) return;
    parts.push(p);
    if (p === "ui") {
      var pu = prev.ui || {},
        cu = cur.ui || {};
      Object.keys(UIKEYLAB).forEach(function (k) {
        if (JSON.stringify(pu[k]) !== JSON.stringify(cu[k]) && words.indexOf(UIKEYLAB[k]) < 0)
          words.push(UIKEYLAB[k]);
      });
    } else words.push(PARTLAB[p]);
  });
  return { parts: parts, summary: words.length ? cap(words.join(", ")) : _T("settings") };
}

function logLoad(cb) {
  if (LOGDATA) return cb(LOGDATA);
  HA.data
    .get("system", LOGKEY)
    .then(function (v) {
      LOGDATA = v && Array.isArray(v.entries) ? v : { v: 1, entries: [] };
      cb(LOGDATA);
    })
    .catch(function () {
      LOGDATA = { v: 1, entries: [] };
      cb(LOGDATA);
    });
}

function logSave() {
  HA.data.set("system", LOGKEY, LOGDATA).catch(function () {});
}

function logChange(pj, cj) {
  if (!pj) return;
  var prev = JSON.parse(pj),
    cur = JSON.parse(cj),
    d = logDiff(prev, cur);
  if (!d.parts.length) return;
  var snap = {};
  d.parts.forEach(function (p) {
    if (p !== "notify") snap[p] = prev[p];
  });
  var now = Date.now(),
    user = (H().user && H().user.name) || _T("admin_2");
  logLoad(function (L) {
    var e = L.entries[0];
    if (e && e.u === user && now - e.t < 60000) {
      Object.keys(snap).forEach(function (p) {
        if (!(p in e.p)) e.p[p] = snap[p];
      });
      e.t = now;
      var w = (e.s + ", " + d.summary.toLowerCase()).split(", "),
        u = [];
      w.forEach(function (x) {
        x = x.toLowerCase();
        if (u.indexOf(x) < 0) u.push(x);
      });
      e.s = cap(u.join(", "));
    } else L.entries.unshift({ t: now, u: user, s: d.summary, p: snap });
    L.entries = L.entries.slice(0, 10);
    logSave();
    var e0 = L.entries[0];
    if (ISADMIN && e0)
      toastAct(_T("saved"), _T("undo_btn"), function () {
        LOGSKIP = true;
        undoEntry(e0);
        LOGDATA.entries = LOGDATA.entries.filter(function (x) {
          return x !== e0;
        });
        logSave();
      });
  });
}

function toastAct(m, label, fn) {
  var old = document.querySelector(".toast.act");
  if (old) old.remove();
  var t = mk("div", "toast pane act");
  t.setAttribute("role", "status");
  var s = document.createElement("span");
  s.textContent = m;
  t.appendChild(s);
  var b = mk("span", "tact");
  b.textContent = label;
  b.addEventListener("click", function () {
    t.remove();
    fn();
  });
  t.appendChild(b);
  document.body.appendChild(t);
  requestAnimationFrame(function () {
    t.classList.add("in");
  });
  setTimeout(function () {
    t.classList.remove("in");
    setTimeout(function () {
      t.remove();
    }, 300);
  }, 7000);
}

function undoEntry(e) {
  var n = JSON.parse(JSON.stringify(STORE));
  Object.keys(e.p).forEach(function (p) {
    if (p === "ui") {
      var u = cleanUI(e.p.ui);
      if (u) n.ui = u;
    } else n[p] = e.p[p];
  });
  var c = cleanStore(n);
  if (!c.ui) c.ui = UI;
  STORE = c;
  UI = c.ui;
  STORE_VER++;
  LOGNEXT = true;
  storeSave();
  applyUI();
  buildDock();
  render();
  toast(_T("change_undone"));
}

function logPage(b) {
  var box = mk("div");
  b.appendChild(box);
  logLoad(function (L) {
    if (!box.isConnected) return;
    redrawBox(box, function () {
      var hint = mk("div", "hint");
      hint.textContent = _T("the_last_ten_changes_to_settings_und");
      box.appendChild(hint);
      if (!L.entries.length)
        box.appendChild(
          pill("info", _T("no_changes_yet"), {
            sub: function () {
              return _T("changes_you_make_in_settings_appear_");
            },
          })
        );
      L.entries.forEach(function (e) {
        var keys = Object.keys(e.p),
          d = new Date(e.t),
          when =
            d.toLocaleDateString(LOC(), { day: "numeric", month: "short" }) +
            " " +
            histTime(e.t / 1000);
        box.appendChild(
          pill("restart", e.s, {
            sub: function () {
              return when + " · " + e.u + (keys.length ? "" : _T("can_t_be_undone"));
            },
            tap: function () {
              if (!keys.length) {
                toast(_T("this_change_can_t_be_undone_here"));
                return;
              }
              confirmDlg(_T("undo") + e.s + _T("from") + when + "?", function () {
                undoEntry(e);
              });
            },
          })
        );
      });
    });
  });
}

/* Notifications: rules that become Home Assistant automations. */

/* ---- notifications (admin): rules become Home Assistant automations ---- */
var NRULES = {
  batt: {
    title: _T("low_battery"),
    icon: "battery",
    desc: _T("when_a_tracked_battery_sensor_drops_"),
  },
  offline: {
    title: _T("device_offline"),
    icon: "alert",
    desc: _T("when_a_device_stays_unavailable_for_"),
  },
  vacuum: {
    title: _T("robot_vacuum_problem"),
    icon: "vac",
    desc: _T("when_the_robot_vacuum_reports_an_err"),
  },
};

function cleanNotify(n) {
  var o = { rules: {} };
  Object.keys(NRULES).forEach(function (k) {
    var r = (n && n.rules && n.rules[k]) || {},
      c = { on: !!r.on, targets: [] };
    (Array.isArray(r.targets) ? r.targets : []).slice(0, 10).forEach(function (x) {
      if (typeof x === "string" && /^[a-z0-9_]{1,60}$/.test(x)) c.targets.push(x);
    });
    if (k === "batt") c.thr = [10, 15, 20, 30].indexOf(r.thr) >= 0 ? r.thr : 20;
    if (k === "offline") c.mins = [5, 10, 15, 30, 60].indexOf(r.mins) >= 0 ? r.mins : 5;
    if (k === "offline" || k === "batt") {
      c.ents = [];
      (Array.isArray(r.ents) ? r.ents : []).slice(0, 150).forEach(function (x) {
        if (typeof x === "string" && ENTRE.test(x)) c.ents.push(x);
      });
      c.scope =
        ["default", "all", "custom"].indexOf(r.scope) >= 0
          ? r.scope
          : c.ents.length
            ? "custom"
            : "default";
    }
    o.rules[k] = c;
  });
  /* Alerts for any entity: when it reaches a state (a washer finished, a door left open, a call). */
  o.watch = [];
  (n && Array.isArray(n.watch) ? n.watch : []).slice(0, 20).forEach(function (w) {
    if (!w || typeof w.id !== "string" || !/^w[a-z0-9]{1,10}$/.test(w.id) || o.watch.some(function (x) { return x.id === w.id; })) return;
    var c = {
      id: w.id,
      name: typeof w.name === "string" ? w.name.slice(0, 40) : "",
      e: typeof w.e === "string" && ENTRE.test(w.e) ? w.e : "",
      to: typeof w.to === "string" ? w.to.slice(0, 40) : "",
      on: !!w.on,
      targets: [],
    };
    (Array.isArray(w.targets) ? w.targets : []).slice(0, 10).forEach(function (x) {
      if (typeof x === "string" && /^[a-z0-9_]{1,60}$/.test(x)) c.targets.push(x);
    });
    o.watch.push(c);
  });
  return o;
}

/* ---- alerts for any entity ---- */

var WATCH_DOMS = ["sensor", "binary_sensor", "select", "input_select", "switch", "input_boolean", "light", "climate", "vacuum", "media_player", "event", "lock", "cover", "fan", "button", "person", "device_tracker", "update", "timer", "counter", "camera"];

function watchRules() {
  if (!STORE.notify) STORE.notify = cleanNotify(null);
  return STORE.notify.watch || (STORE.notify.watch = []);
}

function watchPayload(w) {
  if (!w.e || !w.to || !w.targets.length) return null;
  var msg = w.name
    ? w.name + ": {{ trigger.to_state.attributes.friendly_name }}"
    : "{{ trigger.to_state.attributes.friendly_name }} is now {{ trigger.to_state.state }}";
  return {
    id: "dashboard_n_" + w.id,
    alias: _T("dashboard_notify") + (w.name || w.e),
    description: _T("managed_by_the_dashboard_app_setting_2"),
    mode: "queued",
    triggers: [{ trigger: "state", entity_id: w.e, to: w.to }],
    conditions: [],
    actions: w.targets.map(function (t) {
      var data = { title: _T("home"), message: msg };
      /* The notification of a door call opens this dashboard when it is tapped, and the dashboard opens the call (app/doorcall.js). `url` is what iOS reads, `clickAction` Android. */
      if (ixIsRing(w.e)) data.data = { url: window.HA.panelPath(), clickAction: window.HA.panelPath() };
      return { action: "notify." + t, data: data };
    }),
  };
}

function syncWatch(w) {
  var p = watchPayload(w);
