  if (a.device_class === "timestamp") {
    var t = Date.parse(s);
    if (isFinite(t)) secs = Math.round((t - Date.now()) / 1000);
  } else if (a.device_class === "duration" && isFinite(Number(s))) {
    var u = a.unit_of_measurement;
