    : kind === "number" || kind === "select"
      ? "tune"
      : kind === "button"
        ? "play"
        : kind === "cover"
          ? "swap"
          : kind === "lock"
            ? "lock"
            : kind === "light"
              ? "light"
              : kind === "media"
                ? /tv/i.test(name)
                  ? "tv"
                  : "media"
                : kind === "climate"
                  ? "ac"
                  : kind === "fan"
                    ? "fan"
                    : kind === "switch"
                      ? "plug"
                      : kind === "vacuum"
                        ? "vac"
                        : kind === "camera"
                          ? "cam"
                          : "plug";
}

