  }).then(changed, function (e) {
    if (IXA.talker === t) IXA.talker = null;
    toast((e && e.userMessage) || _T("px_talking_did_not_start"));
    changed();
  });
}

function ixAudioStop() {
  ixListenStop();
  ixTalkStop();
  IXA.silent = false; // the next call starts with sound again
}

